INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429814, 16690, 'South China Morning Post', 'en', 'China strips former generals Zhang Youxia and Liu Zhenli of top military positions', 'https://www.scmp.com/news/china/military/article/3365646/china-strips-former-generals-zhang-youxia-and-liu-zhenli-top-military-positions', 'Beijing has formally removed former senior officers Zhang Youxia and Liu Zhenli as members of China’s supreme military command. The two generals have been under investigation for alleged discipline violations since January and were officially stripped of their positions on the Central Military Commission (CMC) at a meeting of the National People’s Congress’ Standing Committee on Friday. As the CMC’s senior vice-chairman, Zhang was the highest-ranking uniformed officer in the Chinese military....', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/1b3e13a3-86c9-48ea-9bc5-580668e8f0dc_8fc21e72.jpg?itok=b5wRMXGa&v=1787922371', '2026-08-28T13:06:16+00:00', '2026-08-29T00:09:28.630074'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
