INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427274, 16727, 'The Guardian', 'en', 'Sweetener used in chewing gum and jam linked to strokes and heart attacks', 'https://www.theguardian.com/society/2026/aug/28/sweetener-xylitol-used-in-chewing-gum-and-jam-linked-to-strokes-and-heart-attacks-study', 'High blood levels of xylitol associated with higher risk of major cardiovascular events, in largest study of its kind A common sweetener used in products such as chewing gum, toothpaste, jam, yoghurts and ice-cream has been linked to an increased risk of strokes, heart attacks and death. Xylitol is a sugar alcohol present in some natural foods in very low amounts. It is also added – often in amounts 1,000 times higher – to artificially sweeten foods, beverages and oral care products. Continue reading...', 'https://i.guim.co.uk/img/media/0e41fcbdbcb187200927d6a13ce7e04594583c76/137_171_4808_3847/master/4808.jpg?width=140&quality=85&auto=format&fit=max&s=12ef4918f29027aa6a4faa1f25434068', '2026-08-28T13:05:16+00:00', '2026-08-29T00:03:22.651267'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
