INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427266, 16743, 'The Guardian', 'en', 'Volunteers rescue man stuck on 10,000ft-high ledge in Sierra Nevada', 'https://www.theguardian.com/us-news/2026/aug/28/volunteers-rescue-man-cliff-sierra-nevada', 'Climber, stuck on 6in ridge, had veered off treacherous path and ‘any fall would almost certainly be fatal’ An ill-fated move left a man stranded on a 6in ledge over 10,000ft off the ground for hours in California’s Sierra Nevada mountain range, before a volunteer rescue team came to his aid. The climber, who has not been publicly identified, had been scaling the Mendenhall couloir, a gully on the face of Laurel mountain, with a friend on Saturday. Continue reading...', 'https://i.guim.co.uk/img/media/4e1079ffb55d92c00ef45a5bc60b2a88b431fad4/37_0_1133_906/master/1133.jpg?width=140&quality=85&auto=format&fit=max&s=b070e7edeedc6daa68c0fd0f62021782', '2026-08-28T21:30:17+00:00', '2026-08-29T00:03:20.541566'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
